/**
 * Writes the iOS client's schema from `shared/db/schema.ts`, and the agent API's text copy of its muscle formula:
 * `bun run generate`. Unlike the apps' other generated files, the outputs are committed, because Xcode and CI build
 * the app without running Bun first.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { generate } from "sync-engine/schema";
import { schema } from "../shared/db/schema";

export const SWIFT_SCHEMA = "app-ios/Sources/Core/Sync/Generated/SyncSchema.swift";
export const MUSCLE_MODEL_SOURCE = "server/src/agent/muscle-model.source.ts";

/**
 * `GET /muscle-effects` serves `muscle-model.ts` verbatim. A text import of the file would do, but Bun's bundler merges
 * it with the server's own import of the same path and drops the text, so the text is a generated string instead.
 */
export function muscleModelSource() {
  const source = readFileSync(join(import.meta.dir, "../server/src/agent/muscle-model.ts"), "utf8");
  return `// Generated by bun run generate from muscle-model.ts. Do not edit.\nexport default ${JSON.stringify(source)};\n`;
}

if (import.meta.main) {
  const swift = join(import.meta.dir, "..", SWIFT_SCHEMA);
  mkdirSync(dirname(swift), { recursive: true });
  generate({ schema, swift });
  console.log(`Wrote ${SWIFT_SCHEMA}`);
  writeFileSync(join(import.meta.dir, "..", MUSCLE_MODEL_SOURCE), muscleModelSource());
  console.log(`Wrote ${MUSCLE_MODEL_SOURCE}`);
}
